
const WORDS=[{"id": 0, "w": "俗话", "p": "súhuà", "t": "名词", "m": "tục ngữ", "coll": "一句俗话、常听的俗话", "s": "老师引用了一句俗话让学生讨论其中包含的生活经验。"}, {"id": 1, "w": "历来", "p": "lìlái", "t": "副词", "m": "xưa nay", "coll": "历来重视、历来如此", "s": "这里的居民历来重视海洋许多习俗都与捕鱼的生活有关。"}, {"id": 2, "w": "维持", "p": "wéichí", "t": "动词", "m": "duy trì, giữ, giữ lại", "coll": "维持生活、维持平衡", "s": "这些生物以独特的方式维持生命活动引起了研究者的兴趣。"}, {"id": 3, "w": "众所周知", "p": "zhòngsuǒzhōuzhī", "t": "成语", "m": "mọi người đều biết", "coll": "众所周知、众所周知的事实", "s": "众所周知海洋覆盖着地球表面的大部分区域，但许多深海环境仍有待探索。"}, {"id": 4, "w": "真理", "p": "zhēnlǐ", "t": "名词", "m": "chân lý", "coll": "追求真理、检验真理", "s": "科学研究需要依据证据不断检验认识努力接近真理。"}, {"id": 5, "w": "认定", "p": "rèndìng", "t": "动词", "m": "nhận định, cho là", "coll": "认定事实、不能认定", "s": "在缺乏证据的情况下我们不能认定某一种解释就是正确答案。"}, {"id": 6, "w": "准则", "p": "zhǔnzé", "t": "名词", "m": "nguyên tắc, quy tắc, tiêu chuẩn", "coll": "行为准则、遵守准则", "s": "开展研究时，所有成员都应该遵守事先确定的工作准则。"}, {"id": 7, "w": "定义", "p": "dìngyì", "t": "名词／动词", "m": "định nghĩa", "coll": "明确的定义、给出定义", "s": "讨论一个概念之前，首先需要说明它的定义和适用范围。"}, {"id": 8, "w": "潜水", "p": "qiánshuǐ", "t": "动词", "m": "lặn", "coll": "潜水设备、潜水活动", "s": "参加潜水活动前，他认真接受培训了解设备的使用方法。"}, {"id": 9, "w": "繁殖", "p": "fánzhí", "t": "动词", "m": "sinh sôi nảy nở, sinh sản", "coll": "繁殖后代、繁殖季节", "s": "每到繁殖季节，这种鸟就会返回熟悉的地方寻找适合筑巢的位置。"}, {"id": 10, "w": "场所", "p": "chǎngsuǒ", "t": "名词", "m": "nơi, nơi chốn", "coll": "公共场所、活动场所", "s": "离开公共场所时，请带走自己的物品不要随意留下垃圾。"}, {"id": 11, "w": "古怪", "p": "gǔguài", "t": "形容词", "m": "cổ quái, kỳ dị", "coll": "性格古怪、古怪的形状", "s": "这块石头形状古怪远远看去像一只伏在地上的小动物。"}, {"id": 12, "w": "贝壳", "p": "bèiké", "t": "名词", "m": "vỏ sò, ốc xà cừ", "coll": "收集贝壳、一枚贝壳", "s": "退潮以后，海滩上留下了许多颜色不同的贝壳。"}, {"id": 13, "w": "诧异", "p": "chàyì", "t": "形容词", "m": "rất kinh ngạc", "coll": "感到诧异、令人诧异", "s": "听到这个与预期不同的结果，他感到诧异随即重新核对了记录。"}, {"id": 14, "w": "样品", "p": "yàngpǐn", "t": "名词", "m": "hàng mẫu, mẫu vật", "coll": "采集样品、检测样品", "s": "研究人员把采集的样品分别装进容器并标明编号和日期。"}, {"id": 15, "w": "刺", "p": "cì", "t": "动词", "m": "đâm, chọc, kích thích", "coll": "刺破皮肤、刺进土里", "s": "他不小心被树枝刺破了手，于是停下来处理伤口。"}, {"id": 16, "w": "气味", "p": "qìwèi", "t": "名词", "m": "mùi", "coll": "闻到气味、特殊气味", "s": "打开盒子以后，一股特殊的气味飘了出来让他立刻想起了家乡。"}, {"id": 17, "w": "恍然大悟", "p": "huǎngrán dà wù", "t": "成语", "m": "bỗng nhiên tỉnh ngộ, chợt hiểu ra", "coll": "恍然大悟、听后恍然大悟", "s": "听完老师的解释她恍然大悟终于明白了问题出在哪里。"}, {"id": 18, "w": "进而", "p": "jìn'ér", "t": "连词", "m": "sau đó", "coll": "进而分析、进而得出结论", "s": "研究者先比较不同的资料进而分析变化背后的可能原因。"}, {"id": 19, "w": "分裂", "p": "fēnliè", "t": "动词", "m": "tách rời, chia, chia rẽ", "coll": "细胞分裂、发生分裂", "s": "这段影像展示了细胞逐渐分裂形成新细胞的过程。"}, {"id": 20, "w": "渗透", "p": "shèntòu", "t": "动词", "m": "thẩm thấu, ngấm vào, thấm", "coll": "逐渐渗透、渗透到内部", "s": "雨水沿着岩石的缝隙慢慢渗透最终流入地下。"}, {"id": 21, "w": "细菌", "p": "xìjūn", "t": "名词", "m": "vi trùng, vi khuẩn", "coll": "观察细菌、细菌培养", "s": "实验人员借助专门的设备观察细菌在不同条件下的变化。"}, {"id": 22, "w": "过滤", "p": "guòlǜ", "t": "动词", "m": "lọc", "coll": "过滤杂质、过滤水", "s": "这个装置可以过滤水中的部分杂质具体效果需要通过检测来确认。"}, {"id": 23, "w": "来源", "p": "láiyuán", "t": "名词", "m": "nguồn gốc, nguồn", "coll": "信息来源、能量来源", "s": "阅读资料时，不仅要关注结论还应该核实信息的来源。"}, {"id": 24, "w": "合成", "p": "héchéng", "t": "动词", "m": "tổng hợp, hợp thành", "coll": "合成材料、合成物质", "s": "研究团队尝试用新的方法合成材料并测试其性能。"}, {"id": 25, "w": "解放", "p": "jiěfàng", "t": "动词", "m": "giải phóng, phóng thích", "coll": "解放双手、解放思想", "s": "这种工具帮助人们解放双手把更多精力投入需要思考的工作。"}, {"id": 26, "w": "迈", "p": "mài", "t": "动词", "m": "bước, sải bước", "coll": "迈出一步、迈向未来", "s": "经过反复考虑，他终于迈出了改变生活的第一步。"}, {"id": 27, "w": "探索", "p": "tànsuǒ", "t": "动词", "m": "thám hiểm, tìm kiếm", "coll": "探索未知、探索规律", "s": "科学家不断探索未知希望进一步了解深海环境中的生命现象。"}, {"id": 28, "w": "据悉", "p": "jùxī", "t": "动词", "m": "theo nguồn tin", "coll": "据悉已经完成、据悉将举行", "s": "据悉，这次考察已经完成了预定区域的样品采集工作。"}, {"id": 29, "w": "忍受", "p": "rěnshòu", "t": "动词", "m": "chịu đựng", "coll": "忍受痛苦、难以忍受", "s": "施工现场的噪音让人难以忍受附近居民希望尽快调整作业时间。"}, {"id": 30, "w": "超越", "p": "chāoyuè", "t": "动词", "m": "vượt qua, hơn hẳn", "coll": "超越自我、超越想象", "s": "深海中发现的奇特景象有时会超越我们原有的想象。"}, {"id": 31, "w": "摄氏度", "p": "shèshìdù", "t": "量词", "m": "độ C", "coll": "三十摄氏度、零摄氏度", "s": "记录表上清楚地写着当时的水温为二十摄氏度。"}, {"id": 32, "w": "丧失", "p": "sàngshī", "t": "动词", "m": "mất đi, mất mát", "coll": "丧失机会、丧失信心", "s": "即使暂时没有找到答案，也不应该轻易丧失信心而要重新检查研究思路。"}, {"id": 33, "w": "偏偏", "p": "piānpiān", "t": "副词", "m": "lại, vẫn cứ, nhưng, riêng", "coll": "偏偏遇上、偏偏不在", "s": "他特意赶来请教老师，却偏偏不在办公室。"}, {"id": 34, "w": "真相", "p": "zhēnxiàng", "t": "名词", "m": "sự thật", "coll": "查明真相、了解真相", "s": "只有认真核对相关证据才能逐步查明事情的真相。"}, {"id": 35, "w": "华丽", "p": "huálì", "t": "形容词", "m": "tráng lệ, lộng lẫy, hoa lệ", "coll": "服装华丽、华丽的装饰", "s": "这座建筑外部装饰十分华丽内部，却保留着简洁的布局。"}, {"id": 36, "w": "阵容", "p": "zhènróng", "t": "名词", "m": "thế trận, đội hình", "coll": "强大的阵容、演出阵容", "s": "这次演出汇集了多位优秀演员阵容十分强大。"}, {"id": 37, "w": "有条不紊", "p": "yǒutiáo bùwěn", "t": "成语", "m": "gọn gàng ngăn nắp, có trật tự", "coll": "有条不紊地工作、安排得有条不紊", "s": "虽然任务很多，大家仍然有条不紊地工作按时完成了准备。"}, {"id": 38, "w": "展现", "p": "zhǎnxiàn", "t": "动词", "m": "bày ra, hiện ra", "coll": "展现风貌、展现成果", "s": "这组照片生动展现了海底世界丰富多样的形态。"}, {"id": 39, "w": "丛", "p": "cóng", "t": "量词", "m": "đống, nhóm, đám, chùm", "coll": "一丛草、一丛灌木", "s": "山路旁有一丛灌木叶片上还挂着清晨的露珠。"}, {"id": 40, "w": "体积", "p": "tǐjī", "t": "名词", "m": "thể tích", "coll": "体积庞大、体积变化", "s": "实验人员记录了材料受热以后体积发生的变化。"}, {"id": 41, "w": "造型", "p": "zàoxíng", "t": "名词", "m": "kiểu, hình dáng, sự tạo hình", "coll": "造型独特、设计造型", "s": "这件工艺品造型独特吸引了许多参观者的目光。"}, {"id": 42, "w": "迷惑", "p": "míhuò", "t": "形容词／动词", "m": "mê muội, mơ hồ", "coll": "感到迷惑、令人迷惑", "s": "面对看似矛盾的资料，她一时感到迷惑，于是决定重新整理线索。"}, {"id": 43, "w": "广阔", "p": "guǎngkuò", "t": "形容词", "m": "bao la, rộng lớn, mênh mông", "coll": "广阔的空间、广阔的海洋", "s": "广阔的海洋蕴藏着许多尚未被我们充分认识的奥秘。"}, {"id": 44, "w": "奇妙", "p": "qímiào", "t": "形容词", "m": "kỳ diệu, tuyệt diệu", "coll": "奇妙的世界、十分奇妙", "s": "显微镜下一滴水也展现出一个奇妙的世界。"}, {"id": 45, "w": "基地", "p": "jīdì", "t": "名词", "m": "căn cứ, nền tảng", "coll": "研究基地、建立基地", "s": "这个研究基地长期承担海洋资料的收集与分析工作。"}];
